local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path;local b=require('_bootstrap');local path=b.lib('path');local file=path.join(b.root,'run.bat');local f=assert(io.open(file,'rb'));local text=f:read('a');f:close();assert(text:sub(1,3)~='\239\187\191','run.bat must not contain a UTF-8 BOM');assert(not text:gsub('\r\n',''):find('\n',1,true),'run.bat must use CRLF line endings');for _,forbidden in ipairs({'cargo ','powershell','taskkill','start_backend','stop_backend'})do assert(not text:lower():find(forbidden,1,true),'run.bat contains workflow logic: '..forbidden)end;assert(text:find([[D:\code\omoba\tools\lua\lua.exe]],1,true),'run.bat missing fixed Lua runtime');assert(text:find([[%~dp0scripts\run.lua]],1,true),'run.bat missing Lua launcher');assert(text:find('%*',1,true),'run.bat must forward arguments');assert(text:lower():find('exit /b %%errorlevel%%')or text:lower():find('exit /b %errorlevel%',1,true),'run.bat must return Lua exit code');print('run.bat Lua wrapper verification passed')
